#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include "systolic_stub.h"

/* generated by ICDeCompiler */
void matmul_requant(int16_t A[8][8], int16_t B[8][8],
                    int32_t acc[8][8], int16_t out[8][8]);

int main(void) {
    int16_t A[8][8], B[8][8], out[8][8];
    int32_t acc[8][8];
    int16_t ref[8][8];

    /* Q8.8: value 1.0 is stored as 256 */
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 8; j++) {
            A[i][j] = (int16_t)((i + 1) * 64);      /* 0.25 .. 2.0 */
            B[i][j] = (int16_t)((j + 1) * 32);      /* 0.125 .. 1.0 */
            acc[i][j] = 0;
            out[i][j] = 0;
        }

    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 8; j++) {
            int32_t sum = 0;
            for (int k = 0; k < 8; k++)
                sum += (int32_t)A[i][k] * (int32_t)B[k][j];
            ref[i][j] = (int16_t)(sum >> 8);
        }

    matmul_requant(A, B, acc, out);

    int bad = 0;
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 8; j++)
            if (out[i][j] != ref[i][j]) {
                if (bad < 5)
                    printf("mismatch [%d][%d]: got %d, expected %d\n",
                           i, j, out[i][j], ref[i][j]);
                bad++;
            }

    if (bad == 0) {
        printf("OK: Q8.8 matmul with requantization matches reference\n");
        return 0;
    }
    printf("FAIL: %d mismatches\n", bad);
    return 1;
}